import type {
  ConnectionConfig,
  DatabaseInfo,
  TableInfo,
  ColumnInfo,
  IndexInfo,
  ForeignKeyInfo,
  TriggerInfo,
  QueryResult,
  SidebarLayout,
} from "@/types/database";
import type { AiConfig } from "@/stores/settingsStore";
import type {
  AiCompletionRequest,
  AiStreamChunk,
  AiConversation,
  UpdateInfo,
  RedisValue,
  RedisScanResult,
